 :root {
   color-scheme: dark;
   --bg: #0a0b0e;
   --bg-raised: #0e1014;
   --text: #f1f2f4;
   --muted: #a2a7b3;
   --faint: #71767f;
   --accent: #8b8cf8;
   --accent-strong: #6366f1;
